function ProductCard({p,lang,t,merchant,priceValue,currency,colorFilter,openProduct,add}:{p:Product;lang:'ar'|'en';t:(ar:string,en:string)=>string;merchant:boolean;priceValue:number;currency:string;colorFilter:string;openProduct:(p:Product,colorIndex?:number,size?:string)=>void;add:(p:Product,q?:number,opt?:string)=>void}){
 const en=lang==='en';
 const filteredColor=p.colors?.findIndex(c=>c.en===colorFilter)??-1;
 const [colorIndex,setColorIndex]=useState(filteredColor>=0?filteredColor:0);
 const chosen=p.colors?.[colorIndex];
 const [size,setSize]=useState(p.sizes?.[1]||p.sizes?.[0]||'');
 const variant=chosen&&size?variantValue(chosen,size):p.options[0];
 return <article className={'product-card '+(!p.available?'product-unavailable':'')}>
   <button className="product-photo" onClick={()=>openProduct(p,colorIndex,size)} aria-label={t('عرض تفاصيل ','View details: ')+(en?p.en:p.ar)}>
     <ProductImage product={p} lang={lang} colorIndex={colorIndex}/>
     {p.badge&&<span className={'product-badge '+(p.badge==='جديد'?'new':'')}>{t(p.badge,p.badge==='جديد'?'New':p.badge==='الأكثر طلبًا'?'Bestseller':'Riwaq selection')}</span>}
     <span className="quick-view"><Eye size={17}/>{t('عرض التفاصيل','View details')}</span>
   </button>
   <div className="product-body">
     <div className="product-meta"><bdi>{p.code}</bdi><span className={p.available?'available':'unavailable'}>{p.available?t('متوفر للطلب','Available to order'):t('غير متوفر','Unavailable')}</span></div>
     <button className="product-title" onClick={()=>openProduct(p,colorIndex,size)}>{en?p.en:p.ar}</button>
     <p className="product-unit">{en?p.unitEn:p.unit} <span>·</span> {t('الحد الأدنى','Min. order')} <bdi>{p.min}</bdi></p>
     {p.colors?.length&&<div className="card-variants"><span className="variant-label">{t('اللون','Color')}</span><div className="swatch-row" role="group" aria-label={t('الألوان المتاحة','Available colors')}>{p.colors.map((c,i)=><button key={i} type="button" disabled={p.available&&!p.sizes?.some(sz=>variantAvailable(p,variantValue(c,sz)))} className={'swatch '+(colorIndex===i?'selected':'')} style={{'--swatch':c.hex} as React.CSSProperties} title={en?c.en:c.ar} aria-label={en?c.en:c.ar} aria-pressed={colorIndex===i} onClick={()=>{setColorIndex(i);if(size&&!variantAvailable(p,variantValue(c,size)))setSize(p.sizes?.find(sz=>variantAvailable(p,variantValue(c,sz)))||'')}}/>)}</div><span className="variant-name" aria-live="polite">{en?chosen?.en:chosen?.ar}</span></div>}
     {p.sizes?.length&&<div className="card-sizes"><span className="variant-label">{t('المقاس','Size')}</span><div className="size-row" role="group" aria-label={t('المقاسات المتاحة','Available sizes')}>{p.sizes.map(s=><button key={s} type="button" disabled={!chosen||!variantAvailable(p,variantValue(chosen,s))} title={chosen&&!variantAvailable(p,variantValue(chosen,s))?t('غير متوفر','Unavailable'):undefined} className={size===s?'selected':''} aria-pressed={size===s} onClick={()=>setSize(s)}><bdi>{s}</bdi></button>)}</div></div>}
     <div className="product-bottom"><strong>{Number.isFinite(priceValue)?money(priceValue,currency):t('السعر غير محدد','Price not set')}<small> / {en?p.unitEn:p.unit}</small></strong></div>
     <button className="card-action" disabled={!variantAvailable(p,variant)||(!!merchant&&!Number.isFinite(priceValue))} onClick={()=>add(p,p.min,variant)}><ShoppingBag size={17}/>{merchant?t('أضف إلى الطلب','Add to request'):t('دخول التاجر للطلب','Sign in to order')}</button>
   </div>
 </article>
}
