   <div className="hero-trust wrap"><div><Tags size={23}/><span><strong>{blk('hero','trust-1','سعرك مرتبط بحسابك','Your assigned pricing')}</strong><small>{blk('hero','trust-1','قائمة أسعار بعملة واضحة','A clear price list and currency',true)}</small></span></div><div><LayoutGrid size={23}/><span><strong>{blk('hero','trust-2','خيارات القطع أمامك','Product options at a glance')}</strong><small>{blk('hero','trust-2','ألوان ومقاسات وحد أدنى للطلب','Colors, sizes and minimums',true)}</small></span></div><div><HeartHandshake size={23}/><span><strong>{blk('hero','trust-3','متابعة من الشركة','Company follow-up')}</strong><small>{blk('hero','trust-3','بعد إرسال الطلب برقم مرجعي','After a numbered request is sent',true)}</small></span></div></div>
