 {shown('categories')&&<section className="section wrap categories-section"><div className="section-heading"><div><span className="eyebrow">{sec('categories','eyebrow','الأقسام','COLLECTIONS')}</span><h2>{sec('categories','title','تسوّق حسب القسم','Shop by category')}</h2></div><button className="text-button" onClick={()=>goTarget(store?.sections.find(item=>item.key==='categories')?.cta_target||'catalog',()=>openCatalog())}>{sec('categories','cta','جميع المنتجات','All products')} <ChevronLeft size={16}/></button></div><div className="category-grid">{categories.filter(c=>c.id&&!c.parentId).map(c=><button className="category-card" key={c.id} onClick={()=>openCatalog(c.id)}><img src={categoryImage(c)} alt="" loading="lazy" onError={e=>{e.currentTarget.style.visibility='hidden'}}/><div className="category-caption"><h3>{en?c.en:c.ar}</h3><small>{productCount(products.filter(p=>descendantIds(categories,c.id||0).has(categories[p.cat]?.id||0)).length)} <ChevronLeft size={16}/></small></div></button>)}</div></section>}
